import { isUndefined } from 'lodash-es';
import React, { PropsWithChildren } from 'react';

import type { Orientation } from '../../../../../core/types/orientation.js';
import { Dimensions } from '../../../types/dimensions.js';
import { LegendSizeContext } from '../../legend/shared/context/LegendSizeContext.js';
import {
  StyledLegendWrapper,
  StyledGraphWrapper,
} from '../chart-layout.styles.js';
import { GraphSizeContext } from '../context/GraphSize.context.js';
import { extractLayoutSlots } from '../functions/extract-layout-slots.js';
import { isVertical } from '../functions/orientation.js';
import { useChartLayoutOrientation } from '../hooks/useChartLayoutOrientation.js';
import { useChartLayoutSize } from '../hooks/useChartLayoutSize.js';
import { useLoading } from '../hooks/useLoading.js';
import { calculateLegendSize } from '../hooks/useResizableLayout.js';
import { OverrideRatioFunction } from '../types.js';

interface FixedChartLayoutProps {
  legendRatio?: number;
  overrideRatio?: OverrideRatioFunction;
  showLegend: boolean;
}

function getLegendSizes(
  orientation: Orientation,
  containerSizes: Dimensions,
  legendRatio: number | undefined,
  overrideRatio: OverrideRatioFunction | undefined,
) {
  return isUndefined(overrideRatio)
    ? calculateLegendSize(
        orientation,
        containerSizes.width,
        containerSizes.height,
        legendRatio,
      )
    : overrideRatio(orientation, containerSizes.width, containerSizes.height);
}

export const FixedChartLayout = ({
  children,
  legendRatio,
  overrideRatio,
  showLegend,
}: PropsWithChildren<FixedChartLayoutProps>) => {
  const { orientation } = useChartLayoutOrientation();
  const containerSizes = useChartLayoutSize();
  const { legendArea, graphArea } = extractLayoutSlots(children);
  const loading = useLoading();

  const legendSizes =
    legendArea && showLegend
      ? getLegendSizes(orientation, containerSizes, legendRatio, overrideRatio)
      : { width: 0, height: 0 };
  const graphSize = {
    width: isVertical(orientation)
      ? containerSizes.width
      : containerSizes.width - legendSizes.width,
    height: isVertical(orientation)
      ? containerSizes.height - legendSizes.height
      : containerSizes.height,
  };

  return (
    <>
      <StyledGraphWrapper $loading={loading}>
        <GraphSizeContext.Provider value={graphSize}>
          {graphArea}
        </GraphSizeContext.Provider>
      </StyledGraphWrapper>
      {showLegend && (
        <StyledLegendWrapper orientation={orientation} $loading={loading}>
          <LegendSizeContext.Provider value={legendSizes}>
            {legendArea}
          </LegendSizeContext.Provider>
        </StyledLegendWrapper>
      )}
    </>
  );
};

FixedChartLayout['displayName'] = 'FixedChartLayout';
